// Integration-only acceptance driver. Historical phone-only and physical-device
// UI probes remain in their original fingerprinted evidence and are not rerun here.
/// Test-process adapter: changes delivery of four genuine authenticated frames,
/// never creates ciphertext, writes keys, or changes the shared DEV transport.
private actor EasyWorkOriginalEventFaultTransport: AgentTransport {
  struct Frame: Sendable, Equatable {
    let cursor: Int
    let ciphertextSHA256: String
    let envelopeIDHash: String
  }
  struct Witness: Sendable {
    let injected: Bool
    let source: [Frame]
    let delivered: [Frame]
    let dropped: [Frame]
    let deliveredCount: Int
    let passthroughEvents: Int
    let pendingFrames: Int
  }
  private let inspector: EasyWorkEnvelopeCrypto
  private let originalCandidate: AgentConnectionCandidate
  private let transportID: String
  private let thread: String
  private var base: LANAgentTransport?
  private var captured: [(Data, Frame)] = []
  private var pending: [(Data, Frame)] = []
  private var source: [Frame] = []
  private var delivered: [Frame] = []
  private var dropped: [Frame] = []
  private var injected = false
  private var passthroughEvents = 0
  private var deliveredCount = 0
  init(credential: EasyWorkCredential, candidate: AgentConnectionCandidate,
    transportID: String, thread: String) throws {
    guard credential.grantRef == nil, candidate.transportId == "lan-wss",
      credential.binding.status == "active" else { throw HostServiceError.wrongHost }
    inspector = try EasyWorkEnvelopeCrypto(credential: credential, binding: credential.binding)
    originalCandidate = candidate; self.transportID = transportID; self.thread = thread
  }
  func make(_ options: AgentTransportOptions) throws -> any AgentTransport {
    guard base == nil, options.bindingId == inspector.binding.bindingId,
      options.grantRef == nil, options.candidate.transportId == transportID,
      options.candidate.endpoint == originalCandidate.endpoint,
      options.candidate.peerFingerprint == originalCandidate.peerFingerprint else {
      throw HostServiceError.wrongHost
    }
    base = try LANAgentTransport(candidate: originalCandidate, bindingId: options.bindingId)
    return self
  }
  func send(_ frame: Data) async throws {
    guard let base else { throw HostServiceError.unavailable }
    try await base.send(frame)
  }
  private func takePending() -> Data {
    let next = pending.removeFirst()
    delivered.append(next.1); deliveredCount += 1
    return next.0
  }
  func receive() async throws -> Data {
    if !pending.isEmpty { return takePending() }
    guard let base else { throw HostServiceError.unavailable }
    while true {
      let data = try await base.receive()
      let (payload, envelopeID) = try inspector.open(data)
      guard payload["kind"] as? String == "protocol",
        let envelope = payload["envelope"] as? [String: Any],
        envelope["kind"] as? String == "event" else { return data }
      let target = try JSONDecoder().decode(EasyWorkTarget.self,
        from: easyWorkJSON(envelope["target"] ?? [:]))
      guard target == inspector.binding.target else { throw HostServiceError.wrongHost }
      guard let event = envelope["payload"] as? [String: Any],
        event["threadId"] as? String == thread else { return data }
      if injected { passthroughEvents += 1; return data }
      guard data.count <= 1024 * 1024, captured.count < 4,
        let cursor = envelope["sequence"] as? Int, cursor > 0,
        source.last.map({ cursor > $0.cursor }) ?? true else {
        throw HostServiceError.invalidResponse
      }
      let frame = Frame(cursor: cursor, ciphertextSHA256: HostService.hash(data),
        envelopeIDHash: HostService.hash(Data(envelopeID.utf8)))
      captured.append((data, frame)); source.append(frame)
      if captured.count < 4 { continue }
      // Newer before older; one identical ciphertext twice; one real gap.
      pending = [captured[3], captured[0], captured[0], captured[2]]
      dropped = [captured[1].1]; captured.removeAll(); injected = true
      return takePending()
    }
  }
  func close() async {
    await base?.close(); base = nil
    captured.removeAll(); pending.removeAll()
  }
  func witness() -> Witness {
    Witness(injected: injected, source: source, delivered: delivered, dropped: dropped,
      deliveredCount: deliveredCount, passthroughEvents: passthroughEvents, pendingFrames: pending.count)
  }
}

/// Delays one genuine, already verified receipt in this test process only.
/// All send paths stay blocked while the UI-owned Store is under examination.
private actor EasyWorkOriginalReceiptGate {
  struct Witness: Sendable {
    let originalQueries: Int
    let held: Bool
    let released: Bool
    let delivered: Int
    let receiptSHA256: String?
    let blockedWrites: [String]
  }
  private let originalID: String
  private var queries = 0
  private var held = false
  private var released = false
  private var closed = false
  private var delivered = 0
  private var digest: String?
  private var originalBytes: Data?
  private var continuation: CheckedContinuation<Void, Never>?
  private var blockedWrites: [String] = []
  init(originalID: String) { self.originalID = originalID }
  func deliver(_ bytes: Data, id: String) async throws -> Data {
    guard !closed else { throw CancellationError() }
    guard id == originalID else { return bytes }
    queries += 1
    guard queries <= 2 else { throw HostServiceError.invalidResponse }
    if queries == 1 {
      digest = HostService.hash(bytes); originalBytes = bytes; held = true
      if !released { await withCheckedContinuation { continuation = $0 } }
    }
    guard !closed else { throw CancellationError() }
    delivered += 1
    return bytes
  }
  func release() { released = true; continuation?.resume(); continuation = nil }
  func cancel() { closed = true; release() }
  func block(_ operation: String) { blockedWrites.append(operation) }
  func capturedBytes() -> Data? { originalBytes }
  func witness() -> Witness {
    Witness(originalQueries: queries, held: held, released: released, delivered: delivered,
      receiptSHA256: digest, blockedWrites: blockedWrites)
  }
}

private struct EasyWorkReceiptGateProvider: AgentClient {
  let base: any AgentClient
  let gate: EasyWorkOriginalReceiptGate
  let originalID: String
  let originalThread: String
  let originalRoot: String
  func workspace(_ client: Client, projectCursor: String?, threadCursor: String?) async throws -> WorkspaceSnapshot {
    try await base.workspace(client, projectCursor: projectCursor, threadCursor: threadCursor)
  }
  func history(_ client: Client, threadId: String, cursor: String?) async throws -> HistorySnapshot {
    try await base.history(client, threadId: threadId, cursor: cursor)
  }
  func receipt(_ client: Client, id: String) async throws -> DeliveryReceipt {
    let receipt = try await base.receipt(client, id: id)
    if id == originalID {
      guard receipt.hostId == client.id, receipt.clientMessageId == originalID,
        receipt.threadId == originalThread, receipt.turnId == originalRoot,
        receipt.state == "submitted", receipt.error == nil else { throw HostServiceError.wrongHost }
    }
    let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
    let bytes = try encoder.encode(receipt)
    guard try await gate.deliver(bytes, id: id) == bytes else { throw HostServiceError.invalidResponse }
    return receipt
  }
  func events(_ client: Client, epoch: String, after: Int, threadId: String) async throws -> EventBatch {
    try await base.events(client, epoch: epoch, after: after, threadId: threadId)
  }
  func models(_ client: Client) async throws -> ModelList { try await base.models(client) }
  func permissionOptions(_ client: Client) -> [AgentPermissionOption] { base.permissionOptions(client) }
  func normalizedCapabilities(_ capabilities: [String], connectionMode: String?) -> [String] {
    base.normalizedCapabilities(capabilities, connectionMode: connectionMode)
  }
  func connectionTitle(_ client: Client) async -> String? { await base.connectionTitle(client) }
  func close(_ client: Client) async { await base.close(client) }
  func send(_ client: Client, reply: PendingReply) async throws -> DeliveryReceipt {
    await gate.block("send"); throw HostServiceError.unavailable
  }
  func sendCapturedReply(_ client: Client, reply: PendingReply, target: AgentRuntimeTarget) async throws -> DeliveryReceipt {
    await gate.block("sendCapturedReply"); throw HostServiceError.unavailable
  }
  func createThread(_ client: Client, projectId: String?, operationId: String) async throws -> Conversation {
    await gate.block("createThread"); throw HostServiceError.unavailable
  }
  func stop(_ client: Client, threadId: String, turnId: String) async throws -> CommandResult {
    await gate.block("stop"); throw HostServiceError.unavailable
  }
  func approve(_ client: Client, approval: Approval, decision: String, answers: [String: [String]]) async throws -> CommandResult {
    await gate.block("approve"); throw HostServiceError.unavailable
  }
  func upload(_ client: Client, threadId: String, file: LocalAttachment, data: Data) async throws -> RemoteAttachment {
    await gate.block("upload"); throw HostServiceError.unavailable
  }
  func download(_ client: Client, file: RemoteAttachment) async throws -> URL {
    await gate.block("download"); throw HostServiceError.unavailable
  }
}

private actor EasyWorkLateEventGate {
  struct Witness: Sendable {
    let sourceHeld: Bool
    let sourceDelivered: Bool
    let destinationHeld: Bool
    let destinationDelivered: Bool
    let sourceBatchSummary: Data?
    let destinationBatchSummary: Data?
    let networkWrites: Int
  }
  private let clientID: String
  private let sourceThreadID: String
  private let destinationThreadID: String
  private let expectedMarker: String
  private var sourceBegun = false, destinationBegun = false
  private var sourceHeld = false, destinationHeld = false
  private var sourceDelivered = false, destinationDelivered = false
  private var sourceReleased = false, destinationReleased = false, cancelled = false
  private var sourceBatchSummary: Data?, destinationBatchSummary: Data?
  private var sourceWaiter: CheckedContinuation<Void, Never>?
  private var destinationWaiter: CheckedContinuation<Void, Never>?

  init(clientID: String, sourceThreadID: String, destinationThreadID: String, expectedMarker: String) {
    self.clientID = clientID; self.sourceThreadID = sourceThreadID
    self.destinationThreadID = destinationThreadID; self.expectedMarker = expectedMarker
  }

  // Reservation happens before the real read. Subsequent polls and other threads pass through.
  func begin(threadID: String) -> Bool {
    guard !cancelled, !clientID.isEmpty, !sourceThreadID.isEmpty, !destinationThreadID.isEmpty,
      sourceThreadID != destinationThreadID, !expectedMarker.isEmpty else { return false }
    if threadID == sourceThreadID, !sourceBegun { sourceBegun = true; return true }
    if threadID == destinationThreadID, !destinationBegun { destinationBegun = true; return true }
    return false
  }

  func hold(_ batch: EventBatch, threadID: String, target: AgentRuntimeTarget, clientID: String) async throws {
    let source = threadID == sourceThreadID
    guard clientID == self.clientID, !self.clientID.isEmpty,
      sourceThreadID != destinationThreadID, !expectedMarker.isEmpty,
      source || threadID == destinationThreadID,
      source ? (sourceBegun && sourceBatchSummary == nil) : (destinationBegun && destinationBatchSummary == nil),
      batch.hostId == self.clientID, !batch.epoch.isEmpty, batch.cursor >= 0,
      batch.ready == true, batch.reset, !batch.events.isEmpty else { throw HostServiceError.invalidResponse }
    var summaries: [[String: Any]] = []
    var markerFound = false
    for event in batch.events {
      let snapshot = event.snapshot
      guard event.threadId == threadID, snapshot.threadId == threadID,
        snapshot.hostId == batch.hostId, let readTarget = snapshot.readTarget,
        readTarget.matchesCapturedPayload(target), let thread = snapshot.thread,
        thread.id == threadID, thread.hostId == batch.hostId else { throw HostServiceError.invalidResponse }
      if let epoch = snapshot.epoch, batch.epoch != target.runtimeId + ":" + epoch { throw HostServiceError.invalidResponse }
      if let cursor = snapshot.cursor, cursor < 0 { throw HostServiceError.invalidResponse }
      if !source && !snapshot.messages.isEmpty { throw HostServiceError.invalidResponse }
      if snapshot.messages.contains(where: { $0.role == "assistant" && $0.text.trimmingCharacters(in: .whitespacesAndNewlines) == expectedMarker }) { markerFound = true }
      let targetData = try JSONEncoder().encode(readTarget)
      let targetObject = try JSONSerialization.jsonObject(with: targetData)
      let messages: [[String: Any]] = snapshot.messages.map { message in
        ["id": message.id, "role": message.role, "textSHA256": HostService.hash(Data(message.text.utf8)),
         "threadId": snapshot.threadId]
      }
      summaries.append(["threadId": event.threadId, "readTarget": targetObject,
        "messages": messages, "runtimeState": snapshot.runtime?.state as Any? ?? NSNull(),
        "threadArchived": thread.archived as Any? ?? NSNull()])
    }
    guard !source || markerFound else { throw HostServiceError.invalidResponse }
    let summary = try easyWorkJSON(["hostId": batch.hostId, "epoch": batch.epoch,
      "cursor": batch.cursor, "reset": batch.reset, "ready": batch.ready == true,
      "threadID": threadID, "events": summaries])
    if source {
      sourceBatchSummary = summary
      if !sourceReleased {
        sourceHeld = true
        await withCheckedContinuation { sourceWaiter = $0 }
        sourceHeld = false
      }
      if !cancelled { sourceDelivered = true }
    } else {
      destinationBatchSummary = summary
      if !destinationReleased {
        destinationHeld = true
        await withCheckedContinuation { destinationWaiter = $0 }
        destinationHeld = false
      }
      if !cancelled { destinationDelivered = true }
    }
    if cancelled { throw CancellationError() }
  }

  func releaseSource() {
    sourceReleased = true
    let waiter = sourceWaiter; sourceWaiter = nil; waiter?.resume()
  }
  func releaseDestination() {
    destinationReleased = true
    let waiter = destinationWaiter; destinationWaiter = nil; waiter?.resume()
  }
  // Test failure cleanup only. Deliberately no task cancellation handler/check in hold.
  func cancelAll() {
    cancelled = true; releaseSource(); releaseDestination()
  }
  func witness() -> Witness {
    Witness(sourceHeld: sourceHeld, sourceDelivered: sourceDelivered,
      destinationHeld: destinationHeld, destinationDelivered: destinationDelivered,
      sourceBatchSummary: sourceBatchSummary, destinationBatchSummary: destinationBatchSummary, networkWrites: 0)
  }
}

private struct EasyWorkLateEventProvider: AgentClient {
  let base: any AgentClient
  let gate: EasyWorkLateEventGate
  let target: AgentRuntimeTarget
  let clientID: String

  private func validate(_ client: Client) throws {
    guard client.id == clientID, let actual = client.agentConnection?.target,
      actual.matchesCapturedPayload(target) else { throw HostServiceError.wrongHost }
  }
  func send(_ client: Client, reply: PendingReply) async throws -> DeliveryReceipt { throw HostServiceError.unavailable }
  func sendCapturedReply(_ client: Client, reply: PendingReply, target: AgentRuntimeTarget) async throws -> DeliveryReceipt { throw HostServiceError.unavailable }
  func receipt(_ client: Client, id: String) async throws -> DeliveryReceipt { try await base.receipt(client, id: id) }
  func workspace(_ client: Client, projectCursor: String?, threadCursor: String?) async throws -> WorkspaceSnapshot { try await base.workspace(client, projectCursor: projectCursor, threadCursor: threadCursor) }
  func history(_ client: Client, threadId: String, cursor: String?) async throws -> HistorySnapshot { try await base.history(client, threadId: threadId, cursor: cursor) }
  func events(_ client: Client, epoch: String, after: Int, threadId: String) async throws -> EventBatch {
    let intercept = await gate.begin(threadID: threadId)
    if intercept { try validate(client) }
    let batch = try await base.events(client, epoch: epoch, after: after, threadId: threadId)
    if intercept { try await gate.hold(batch, threadID: threadId, target: target, clientID: client.id) }
    return batch
  }
  func models(_ client: Client) async throws -> ModelList { try await base.models(client) }
  func projectGit(_ client: Client, projectId: String, target: AgentRuntimeTarget, refresh: Bool) async throws -> Data { try await base.projectGit(client, projectId: projectId, target: target, refresh: refresh) }
  func projectGitFiles(_ client: Client, projectId: String, target: AgentRuntimeTarget, snapshotId: String, worktreeId: String, cursor: String?) async throws -> Data { try await base.projectGitFiles(client, projectId: projectId, target: target, snapshotId: snapshotId, worktreeId: worktreeId, cursor: cursor) }
  func usage(_ client: Client, target: AgentRuntimeTarget) async throws -> Data { try await base.usage(client, target: target) }
  func voiceReadiness(_ client: Client) async throws -> VoiceTranscriptionReadiness { try await base.voiceReadiness(client) }
  func nextTurnSuggestion(_ client: Client, scope: DesktopSuggestionScope) async throws -> DesktopSuggestionResponse { try await base.nextTurnSuggestion(client, scope: scope) }
  func replyDeliveryStatus(_ client: Client, reply: PendingReply, target: AgentRuntimeTarget) async throws -> ReplyDeliveryInspection { try await base.replyDeliveryStatus(client, reply: reply, target: target) }
  func threadCreationStatus(_ client: Client, projectId: String?, operationId: String) async throws -> Conversation? { try await base.threadCreationStatus(client, projectId: projectId, operationId: operationId) }
  func workspaceManagementStatus(_ client: Client, request: WorkspaceManagementRequest) async throws -> WorkspaceManagementOperation { try await base.workspaceManagementStatus(client, request: request) }
  func download(_ client: Client, file: RemoteAttachment) async throws -> URL { try await base.download(client, file: file) }
  func cachedDownload(_ client: Client, file: RemoteAttachment) async throws -> URL? { try await base.cachedDownload(client, file: file) }
  func resolveMessageFile(_ client: Client, threadId: String, messageId: String, reference: String) async throws -> RemoteAttachment { try await base.resolveMessageFile(client, threadId: threadId, messageId: messageId, reference: reference) }
  func fileTransfers(_ client: Client) async throws -> ComputerFileCatalog { try await base.fileTransfers(client) }
  func fileTransfer(_ client: Client, id: String) async throws -> ComputerFileReceipt { try await base.fileTransfer(client, id: id) }
  func notificationEvents(_ client: Client, deviceId: String, after: String) async throws -> TaskNotificationFeed { try await base.notificationEvents(client, deviceId: deviceId, after: after) }
  func openStatus(_ client: Client, threadId: String, operationId: String) async throws -> DesktopOpenOperation { try await base.openStatus(client, threadId: threadId, operationId: operationId) }
  func chatActionStatus(_ client: Client, threadId: String, operationId: String) async throws -> ChatActionReceipt { try await base.chatActionStatus(client, threadId: threadId, operationId: operationId) }
  func searchHistory(_ client: Client, threadId: String, cursor: String?) async throws -> HistorySnapshot { try await base.searchHistory(client, threadId: threadId, cursor: cursor) }
  func forkOptions(_ client: Client, threadId: String) async throws -> ThreadForkOptions { try await base.forkOptions(client, threadId: threadId) }
  func forkStatus(_ client: Client, threadId: String, operationId: String) async throws -> ThreadForkOperation { try await base.forkStatus(client, threadId: threadId, operationId: operationId) }
  func creation(_ client: Client, id: String) async throws -> DesktopCreationOperation { try await base.creation(client, id: id) }
  func creationReceipt(_ client: Client, id: String) async throws -> DesktopCreationOperation { try await base.creationReceipt(client, id: id) }
  func permissionOptions(_ client: Client) -> [AgentPermissionOption] { base.permissionOptions(client) }
  func normalizedCapabilities(_ capabilities: [String], connectionMode: String?) -> [String] { base.normalizedCapabilities(capabilities, connectionMode: connectionMode) }
  func connectionTitle(_ client: Client) async -> String? { await base.connectionTitle(client) }
  func close(_ client: Client) async { await base.close(client) }

  // Remaining protocol defaults reject business writes; required non-default writes follow.
  func createThread(_ client: Client, projectId: String?, operationId: String) async throws -> Conversation { throw HostServiceError.unavailable }
  func stop(_ client: Client, threadId: String, turnId: String) async throws -> CommandResult { throw HostServiceError.unavailable }
  func approve(_ client: Client, approval: Approval, decision: String, answers: [String: [String]]) async throws -> CommandResult { throw HostServiceError.unavailable }
  func upload(_ client: Client, threadId: String, file: LocalAttachment, data: Data) async throws -> RemoteAttachment { throw HostServiceError.unavailable }
}


private actor EasyWorkLateMissingReceiptGate {
  struct Witness: Sendable {
    let originalQueryCalls: Int
    let originalErrorHeld: Bool
    let originalErrorDelivered: Bool
    let originalErrorSHA256: String?
    let secondHeld: Bool
    let secondID: String?
    let secondPending: Data?
    let secondSendCalls: Int
    let forwardedInputs: Int
  }

  private let clientID: String
  private let threadID: String
  private let originalID: String
  private let secondBody: String
  private var originalQueryCalls = 0
  private var originalErrorHeld = false
  private var originalErrorDelivered = false
  private var originalErrorSHA256: String?
  private var secondHeld = false
  private var secondID: String?
  private var secondPending: Data?
  private var secondSendCalls = 0
  private var originalReleased = false
  private var secondEnded = false
  private var cancelled = false
  private var originalWaiter: CheckedContinuation<Void, Never>?
  private var secondWaiter: CheckedContinuation<Void, Never>?

  init(clientID: String, threadID: String, originalID: String, secondBody: String) {
    self.clientID = clientID; self.threadID = threadID
    self.originalID = originalID; self.secondBody = secondBody
  }

  func isOriginal(_ id: String) -> Bool { id == originalID }

  func beginOriginal(clientID: String, id: String) throws {
    guard !cancelled else { throw CancellationError() }
    guard clientID == self.clientID, id == originalID, !threadID.isEmpty,
      !originalID.isEmpty, originalQueryCalls == 0 else { throw HostServiceError.invalidResponse }
    originalQueryCalls += 1
  }

  func holdOriginalError(_ message: String) async throws {
    guard !cancelled else { throw CancellationError() }
    guard originalQueryCalls == 1, originalErrorSHA256 == nil,
      message == L10n.tr("Host 尚未找到此操作回执，请先核对桌面历史。原消息和操作 ID 已保留。") else {
      throw HostServiceError.invalidResponse
    }
    originalErrorSHA256 = HostService.hash(Data(message.utf8))
    try await withTaskCancellationHandler {
      try Task.checkCancellation()
      guard !cancelled else { throw CancellationError() }
      if !originalReleased {
        originalErrorHeld = true
        await withCheckedContinuation { originalWaiter = $0 }
        originalErrorHeld = false
      }
      try Task.checkCancellation()
      guard !cancelled else { throw CancellationError() }
      originalErrorDelivered = true
    } onCancel: { Task { await self.cancelAll() } }
  }

  func holdSecond(_ pending: Data) async throws {
    secondSendCalls += 1
    guard !cancelled else { throw CancellationError() }
    let reply = try JSONDecoder().decode(PendingReply.self, from: pending)
    guard secondSendCalls == 1, reply.hostId == clientID, reply.threadId == threadID,
      !secondBody.isEmpty, reply.text == secondBody, !reply.clientMessageId.isEmpty,
      reply.clientMessageId != originalID, UUID(uuidString: reply.clientMessageId) != nil,
      reply.attachmentIds.isEmpty, reply.sourceAttachments?.isEmpty != false else { throw HostServiceError.invalidResponse }
    secondID = reply.clientMessageId; secondPending = pending
    try await withTaskCancellationHandler {
      try Task.checkCancellation()
      guard !cancelled else { throw CancellationError() }
      if !secondEnded {
        secondHeld = true
        await withCheckedContinuation { secondWaiter = $0 }
        secondHeld = false
      }
      throw CancellationError()
    } onCancel: { Task { await self.cancelAll() } }
  }

  func releaseOriginalError() {
    originalReleased = true
    let waiter = originalWaiter; originalWaiter = nil; waiter?.resume()
  }
  func endSecond() {
    secondEnded = true
    let waiter = secondWaiter; secondWaiter = nil; waiter?.resume()
  }
  func cancelAll() {
    guard !cancelled else { return }
    cancelled = true; releaseOriginalError(); endSecond()
  }
  func witness() -> Witness {
    Witness(originalQueryCalls: originalQueryCalls, originalErrorHeld: originalErrorHeld,
      originalErrorDelivered: originalErrorDelivered, originalErrorSHA256: originalErrorSHA256,
      secondHeld: secondHeld, secondID: secondID, secondPending: secondPending,
      secondSendCalls: secondSendCalls, forwardedInputs: 0)
  }
}

private struct EasyWorkLateMissingReceiptProvider: AgentClient {
  let base: any AgentClient
  let gate: EasyWorkLateMissingReceiptGate
  let target: AgentRuntimeTarget
  let clientID: String
  let threadID: String

  private func validate(_ client: Client) throws {
    guard client.id == clientID, let actual = client.agentConnection?.target,
      actual.matchesCapturedPayload(target) else { throw HostServiceError.wrongHost }
  }
  func receipt(_ client: Client, id: String) async throws -> DeliveryReceipt {
    guard await gate.isOriginal(id) else { return try await base.receipt(client, id: id) }
    try validate(client)
    try await gate.beginOriginal(clientID: client.id, id: id)
    do { return try await base.receipt(client, id: id) }
    catch let error as HostServiceError {
      guard case .message(let message) = error,
        message == L10n.tr("Host 尚未找到此操作回执，请先核对桌面历史。原消息和操作 ID 已保留。") else { throw error }
      try await gate.holdOriginalError(message)
      throw error
    }
  }
  func send(_ client: Client, reply: PendingReply) async throws -> DeliveryReceipt {
    throw HostServiceError.unavailable
  }
  func sendCapturedReply(_ client: Client, reply: PendingReply, target captured: AgentRuntimeTarget) async throws -> DeliveryReceipt {
    try validate(client)
    guard captured.matchesCapturedPayload(target), reply.hostId == clientID,
      reply.threadId == threadID else { throw HostServiceError.wrongHost }
    let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
    try await gate.holdSecond(encoder.encode(reply))
    throw CancellationError()
  }

  func workspace(_ client: Client, projectCursor: String?, threadCursor: String?) async throws -> WorkspaceSnapshot { try await base.workspace(client, projectCursor: projectCursor, threadCursor: threadCursor) }
  func history(_ client: Client, threadId: String, cursor: String?) async throws -> HistorySnapshot { try await base.history(client, threadId: threadId, cursor: cursor) }
  func events(_ client: Client, epoch: String, after: Int, threadId: String) async throws -> EventBatch { try await base.events(client, epoch: epoch, after: after, threadId: threadId) }
  func models(_ client: Client) async throws -> ModelList { try await base.models(client) }
