      report["status"] = "passed-simulator-own-receipt-and-foreign-device-status-isolation-no-replay"
      try save()
    } catch {
      report["status"] = "failed-status-only-no-replay"; report["failure"] = error.localizedDescription
      try? save(); throw error
    }
    #endif
  }

